@import 'tailwindcss';

/* The components live in the docs app's registry, outside this project, so
   Tailwind's automatic source detection never sees their class names. The
   optics panel is shared with the home stage and lives outside the registry,
   so it needs saying separately — named as one file rather than the whole
   components directory, which would compile the docs site's chrome into this
   bundle for nothing. */
@source '../../../www/registry/liqui';
@source '../../../www/components/glass-controls.tsx';

* {
  margin: 0;
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  font-family:
    'SF Pro Text',
    -apple-system,
    BlinkMacSystemFont,
    'Segoe UI',
    Inter,
    sans-serif;
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
}

/* ---- desktop / wallpaper ---------------------------------------------- */

.desktop {
  position: relative;
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #b9b4ad;
}

[data-theme='dark'] .desktop {
  background: #191a2b;
}

/* macOS desktop chrome — wallpaper, menu bar, dock. Assets are @2x,
   rendered at @1x sizes. */
.os {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.os__wallpaper {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: opacity 0.5s ease;
}

.os__wallpaper--dark {
  opacity: 0;
}

[data-theme='dark'] .os__wallpaper--dark {
  opacity: 1;
}

.os__menubar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 5px 20px 5px 10px;
  z-index: 1;
}

.os__menubar img {
  display: block;
}

.os__dock {
  position: absolute;
  bottom: 10px;
  left: 50%;
  transform: translateX(-50%);
  width: min(1153px, 92vw);
}

.os__dock-img {
  display: block;
  width: 100%;
  height: auto;
  transition: opacity 0.5s ease;
}

.os__dock-img--dark {
  position: absolute;
  inset: 0;
  opacity: 0;
}

[data-theme='dark'] .os__dock-img--dark {
  opacity: 1;
}

/* ---- component stage ---------------------------------------------------- */

/* Components sit straight on the wallpaper (not on a host card) so each one
   refracts the background directly — glass stacked on glass muddies the rim
   and hides exactly what these dials are for. */
.stage {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: flex-start;
  gap: 28px;
  /* The settings panel is fixed to the right edge, so the stage centers in
     what's left of the desktop rather than in the viewport. */
  width: min(1000px, calc(100vw - 380px));
  margin-right: 280px;
  max-height: calc(100vh - 180px);
  overflow: auto;
  padding: 4px;
}

.stage__col {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* Labels have no glass under them, so they carry their own contrast. */
.stage__label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(20, 24, 46, 0.72);
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.45);
}

[data-theme='dark'] .stage__label {
  color: rgba(240, 242, 255, 0.75);
  text-shadow: 0 1px 3px rgba(0, 0, 10, 0.5);
}

.stage__label--spaced {
  margin-top: 14px;
}

.stage__form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.stage__buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.stage__checks {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* Checkbox and field labels sit on bare wallpaper rather than on glass, so they
   need a shadow to stay legible. Targeted by element rather than by component
   class: the components are Tailwind-styled now and expose no stable hooks. */
.stage__checks label,
.stage__form label,
.stage__form p {
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.35);
}

[data-theme='dark'] .stage__checks label,
[data-theme='dark'] .stage__form label,
[data-theme='dark'] .stage__form p {
  text-shadow: 0 1px 3px rgba(0, 0, 10, 0.45);
}

/* Slider labels and values are divs, not labels, so they miss the rule above.
   text-shadow inherits, so one declaration on the container covers both. */
.stage__sliders {
  display: flex;
  flex-direction: column;
  gap: 18px;
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.35);
}

[data-theme='dark'] .stage__sliders {
  text-shadow: 0 1px 3px rgba(0, 0, 10, 0.45);
}

/* Progress labels and values are spans in a plain div, so they miss the label
   rule above. Same fix as the sliders: one inherited declaration. */
.stage__progress {
  display: flex;
  flex-direction: column;
  gap: 18px;
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.35);
}

[data-theme='dark'] .stage__progress {
  text-shadow: 0 1px 3px rgba(0, 0, 10, 0.45);
}

/* A tab panel is body copy sitting on bare wallpaper, same problem the slider
   labels have — and it inherits, so one declaration covers the panel and the
   inactive tab labels above it. */
.stage__tabs {
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.35);
}

[data-theme='dark'] .stage__tabs {
  text-shadow: 0 1px 3px rgba(0, 0, 10, 0.45);
}

.stage code {
  font-family: 'SF Mono', ui-monospace, monospace;
  font-size: 0.92em;
  padding: 1px 4px;
  border-radius: 5px;
  background: color-mix(in srgb, var(--lq-text) 10%, transparent);
}

/* ---- settings panel ----------------------------------------------------- */

.panel-wrap {
  position: absolute;
  top: 24px;
  right: 24px;
  z-index: 2;
}

/* Direct child, not any descendant. The panel's own rows are glass now — the
   select triggers inside it are `LiquiGlass` surfaces with a content wrapper of
   the same class — and a descendant selector laid this column layout over every
   one of them, which stacked each trigger's label above its chevron. */
.panel > .liqui-glass__content {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 16px 18px;
  width: 240px;
}

.panel__title {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--lq-text-dim);
}

/* ---- dock --------------------------------------------------------------- */

.dock-wrap {
  position: absolute;
  top: 44px;
  left: 24px;
  z-index: 2;
}

/* Direct child, for the reason above: nothing nests glass in the dock today,
   and the day something does it should not inherit the bar's row layout. */
.dock > .liqui-glass__content {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 18px;
}

.dock__button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: none;
  background: transparent;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--lq-text);
  cursor: pointer;
  padding: 4px 6px;
  border-radius: 10px;
}

.dock__button:hover {
  background: var(--lq-highlight);
}

.dock__divider {
  width: 1px;
  height: 18px;
  background: color-mix(in srgb, var(--lq-text) 18%, transparent);
}

.dock__note {
  font-size: 12.5px;
  color: var(--lq-text);
}

.dock__note-dim {
  color: var(--lq-text-dim);
}

.dock__note--action {
  font-weight: 600;
  color: var(--lq-accent);
}

@import 'tailwindcss';

/* Same reason as demo/app.css: the components live in the docs app's registry,
   outside Tailwind's automatic source detection. */
@source '../../../www/registry/liqui';

* {
  margin: 0;
  box-sizing: border-box;
}

body {
  font-family:
    'SF Pro Text',
    -apple-system,
    BlinkMacSystemFont,
    'Segoe UI',
    Inter,
    sans-serif;
  -webkit-font-smoothing: antialiased;
  background: #f2f2f4;
  color: #16161a;
}

[data-theme='dark'] body {
  background: #0d0d10;
  color: #ececf1;
}

@import 'tailwindcss';
@import 'fumadocs-ui/css/neutral.css';
@import 'fumadocs-ui/css/preset.css';

/* The glass design tokens. Registry users receive the same values through each
   item's `cssVars`; the docs site imports the stylesheet directly because it
   consumes @liqui-design/glass as a workspace package, not through the CLI. */
@import '@liqui-design/glass/tokens.css';

/* Tailwind v4 discovers sources from the project root but stops at
   node_modules, and @liqui-design/glass is symlinked in there. */
@source '../../../packages/glass/src';

html {
  scrollbar-gutter: stable;
}

html > body[data-scroll-locked] {
  margin-right: 0px !important;
  --removed-body-scroll-bar-size: 0px !important;
}

'use client';

import * as React from 'react';

import { Button } from '@/registry/liqui/ui/button';
import { Field, FieldControl, FieldError, FieldLabel } from '@/registry/liqui/ui/field';
import { Form } from '@/registry/liqui/ui/form';

/**
 * The point of `Form` is the `errors` prop. Submit with the handle `admin` and
 * the (pretend) server rejects it — the message lands on that field's own
 * `FieldError`, under that field's own surface, and clears itself the moment
 * you type. No banner, no scroll to the top of the page.
 */
export default function FormDemo() {
  const [errors, setErrors] = React.useState<Record<string, string | string[]>>({});
  const [pending, setPending] = React.useState(false);

  return (
    <Form
      className="w-72"
      errors={errors}
      onSubmit={async (event) => {
        event.preventDefault();
        const handle = String(new FormData(event.currentTarget).get('handle') ?? '');

        setPending(true);
        await new Promise((resolve) => setTimeout(resolve, 500));
        setPending(false);

        setErrors(handle === 'admin' ? { handle: 'That handle is reserved.' } : {});
      }}
    >
      <Field name="handle">
        <FieldLabel>Handle</FieldLabel>
        <FieldControl required placeholder="try “admin”" />
        <FieldError match="valueMissing">A handle is required.</FieldError>
        <FieldError />
      </Field>

      <Button type="submit" variant="accent" disabled={pending}>
        {pending ? 'Checking…' : 'Claim handle'}
      </Button>
    </Form>
  );
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

'use client';

import { Button as BaseButton } from '@base-ui/react/button';
import { LiquiGlass, type LiquiGlassProps } from '@liqui-design/glass';
import { cva, type VariantProps } from 'class-variance-authority';

import { cn } from '@/lib/utils';

/**
 * liqui Button — one component, two materials, chosen by what the button means.
 *
 * **`glass`** (the default) is a Base UI button rendered as a LiquiGlass
 * surface. The glass anatomy (backdrop/tint/specular layers + a content
 * wrapper) can't live inside a native `<button>`: its content model is phrasing
 * content, so the wrapper div would be invalid HTML. `nativeButton={false}` is
 * Base UI's supported escape — useButton then supplies `role="button"`,
 * `tabIndex`, and the Enter/Space handlers itself. The one thing it can't give
 * back is implicit form submission.
 *
 * **`accent` and `danger`** are flat: a solid fill, a real `<button>`, nothing
 * stacked behind the label. This is the library's dividing line and it is
 * Apple's — **glass is for the surfaces you act *through*, and a solid fill is
 * for a control that carries meaning.** A tinted lens is a contradiction: the
 * whole point of the colour is that it says "this is the one", and the whole
 * point of the lens is that it lets the wallpaper through. Accent over a dark
 * photo and accent over a light one used to be two different colours.
 *
 * Because they are native buttons, these two also get **implicit form
 * submission** back — `<Button type="submit" variant="accent">` submits.
 *
 * [Checkbox](/docs/components/checkbox), [Radio](/docs/components/radio-group),
 * [Toggle](/docs/components/toggle) and [Switch](/docs/components/switch) are
 * flat throughout, for the same reason: they carry a value rather than perform
 * an action.
 */

const glassButtonVariants = cva(
  'group inline-flex cursor-default select-none outline-none transition-[transform,box-shadow] duration-150 data-[pressed]:scale-[0.97] active:scale-[0.97] data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50 focus-visible:shadow-[0_0_0_3px_color-mix(in_srgb,var(--lq-accent)_40%,transparent)]',
);

const glassButtonContentVariants = cva(
  'inline-flex items-center justify-center rounded-[inherit] font-semibold leading-tight whitespace-nowrap group-hover:bg-[color-mix(in_srgb,var(--lq-highlight)_40%,transparent)] group-data-[disabled]:bg-transparent',
  {
    variants: {
      size: {
        sm: 'gap-1.5 px-3 py-1.5 text-xs',
        md: 'gap-[7px] px-4 py-[9px] text-[13.5px]',
      },
    },
    defaultVariants: { size: 'md' },
  },
);

const solidButtonVariants = cva(
  cn(
    'inline-flex cursor-default select-none items-center justify-center',
    // `leading-tight` lives with each size below, not here. tailwind-merge
    // drops an earlier `leading-*` when a later `text-{size}` could have
    // carried one (Tailwind's `text-sm/6` syntax), so a line height written
    // before the font size silently loses and the label inherits the page's.
    'border-none font-semibold whitespace-nowrap text-white',
    'outline-none transition-[background-color,transform] duration-150',
    'data-[pressed]:scale-[0.97] active:scale-[0.97]',
    // An outline rather than a box-shadow ring: `outline-offset` leaves the gap
    // Apple leaves, and it reads against the fill without having to be mixed
    // out of it. The same ring Checkbox, Radio and Switch use.
    'focus-visible:outline-2 focus-visible:outline-offset-[3px]',
    'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50',
  ),
  {
    variants: {
      // `glass` is declared so the variant union is one list rather than two,
      // and left empty: the glass surface is a component, not a class string,
      // so `Button` branches before it ever asks for these.
      variant: {
        glass: '',
        accent: cn(
          'bg-[var(--lq-accent)]',
          'hover:not-data-disabled:bg-[color-mix(in_srgb,white_14%,var(--lq-accent))]',
          'focus-visible:outline-[color-mix(in_srgb,var(--lq-accent)_70%,transparent)]',
        ),
        danger: cn(
          'bg-[var(--lq-danger)]',
          'hover:not-data-disabled:bg-[color-mix(in_srgb,white_14%,var(--lq-danger))]',
          'focus-visible:outline-[color-mix(in_srgb,var(--lq-danger)_70%,transparent)]',
        ),
      },
      size: {
        sm: 'gap-1.5 px-3 py-1.5 text-xs leading-tight',
        md: 'gap-[7px] px-4 py-[9px] text-[13.5px] leading-tight',
      },
    },
    defaultVariants: { variant: 'accent', size: 'md' },
  },
);

const BUTTON_GLASS = {
  radius: 12,
  blur: 1,
  refraction: 45,
  bezel: 11,
} satisfies Partial<LiquiGlassProps>;

export interface ButtonProps
  extends BaseButton.Props,
    VariantProps<typeof solidButtonVariants> {
  /**
   * Overrides for the underlying glass surface (radius, refraction, bezel…).
   *
   * A solid variant has no glass to reach, so the optical dials are ignored
   * there — `radius` is the exception, because it is geometry rather than
   * optics and a round accent button (a transport play button, say) still needs
   * to be able to say so.
   */
  glass?: Partial<LiquiGlassProps>;
}

export function Button({
  variant = 'glass',
  size = 'md',
  glass,
  className,
  style,
  ...props
}: ButtonProps) {
  if (variant !== 'glass') {
    return (
      <BaseButton
        {...props}
        style={{ borderRadius: glass?.radius ?? BUTTON_GLASS.radius, ...style }}
        className={cn(solidButtonVariants({ variant, size }), className)}
      />
    );
  }

  return (
    <BaseButton
      {...props}
      style={style}
      nativeButton={false}
      className={cn(glassButtonVariants(), className)}
      render={
        <LiquiGlass
          {...BUTTON_GLASS}
          {...glass}
          contentClassName={glassButtonContentVariants({ size })}
        />
      }
    />
  );
}

/**
 * The class builder for the solid variants, for the times you need a link or a
 * third-party trigger to look like an accent button:
 *
 * ```tsx
 * <a href="/pricing" className={buttonVariants({ variant: 'accent' })}>Upgrade</a>
 * ```
 *
 * It defaults to `accent` rather than to `Button`'s own default, because the
 * glass surface is four stacked layers and a class string cannot be one.
 */
export { solidButtonVariants as buttonVariants };

'use client';

import { Field as BaseField } from '@base-ui/react/field';
import { LiquiGlass, type LiquiGlassProps } from '@liqui-design/glass';

import { cn } from '@/lib/utils';

/**
 * liqui Field — Base UI field with the control sitting on its own glass
 * surface.
 *
 * The `<input>` stays a plain transparent element *inside* the glass content
 * layer. Making the input itself the glass root would put the backdrop and tint
 * layers inside a replaced element, where they cannot render at all.
 *
 * Focus and invalid rings live on the surface, not the input, and are driven by
 * `has-*` so the glass reacts to a state that belongs to its child.
 */

const CONTROL_GLASS = {
  radius: 12,
  blur: 1,
  refraction: 60,
  bezel: 12,
} satisfies Partial<LiquiGlassProps>;

export function Field({ className, ...props }: BaseField.Root.Props) {
  return <BaseField.Root {...props} className={cn('flex flex-col gap-1.5', className)} />;
}

export function FieldLabel({ className, ...props }: BaseField.Label.Props) {
  return (
    <BaseField.Label
      {...props}
      className={cn('text-[12.5px] font-semibold text-[var(--lq-text)]', className)}
    />
  );
}

export function FieldDescription({ className, ...props }: BaseField.Description.Props) {
  return (
    <BaseField.Description
      {...props}
      className={cn('text-xs text-[var(--lq-text-dim)]', className)}
    />
  );
}

export function FieldError({ className, ...props }: BaseField.Error.Props) {
  return (
    <BaseField.Error
      {...props}
      className={cn('text-xs font-semibold text-[var(--lq-danger-text)]', className)}
    />
  );
}

export function FieldControl({
  glass,
  className,
  ...props
}: BaseField.Control.Props & { glass?: Partial<LiquiGlassProps> }) {
  return (
    <LiquiGlass
      {...CONTROL_GLASS}
      {...glass}
      className={cn(
        'transition-shadow duration-150',
        'has-[input:focus-visible]:shadow-[0_0_0_3px_color-mix(in_srgb,var(--lq-accent)_35%,transparent)]',
        'has-[input[data-invalid][data-touched]]:shadow-[0_0_0_2px_color-mix(in_srgb,var(--lq-danger)_55%,transparent)]',
      )}
    >
      <BaseField.Control
        {...props}
        className={cn(
          'block w-full border-none bg-transparent px-3 py-[9px] font-[inherit] text-[13.5px] text-[var(--lq-text)] outline-none',
          'placeholder:text-[var(--lq-text-dim)]',
          'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-55',
          className,
        )}
      />
    </LiquiGlass>
  );
}

export const FieldValidity = BaseField.Validity;

{
